from ...templatesession import new_session

from .base_btssm import BaseBtssmInterface


class InstallInterface(BaseBtssmInterface):
    """Keywords related to BTS SM installation."""

    def install_btssm(self, installer_file, mode='Clean', **kwargs):
        """Installs BTS SM from given installer file.

        :param string installer_file: Path to the installer file.
        :param string mode: Installation type. Supported types (case sensitive):
                            * Clean - remove old installations
                            * Normal - retain old installations
        """
        installer_file = installer_file.strip() if installer_file is not None else None
        mode = mode.strip()
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            new_path = session.btssm.copy_local_installer(installer_file)
            session.btssm.add_exec_permissions(new_path)
            session.btssm.install_btssm(new_path, mode)

    def get_btssm_installer_version(self, installer_path, **kwargs):
        """Returns the version of BTS SM installed by given installer file.

        :param string installer_path: Path to the installer file.

        :return: BTSSM installer version.
        :rtype: string
        """
        installer_path = installer_path.strip() if installer_path is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            return session.btssm.get_installer_version(installer_path)

    def is_btssm_installed(self, filter_expression='*', **kwargs):
        """Returns true if BTS Site Manager is installed and if it has at least one NodeManager matching given filter expression; false otherwise.

        :param string filter_expression: Expression used to filter available versions (passed to the ls command).

        :return: True if application is installed.
        :rtype: boolean
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            return session.btssm.is_installed(filter_expression)

    def get_parameter_dictionary(self, btssm_version, param_dictionary_path, **kwargs):
        """Extracts the LTE Parameter Dictionary from given version of BTSSM.

        :param string btssm_version: Version of BTS Site Manager.
        :param string param_dictionary_path: Path to which the extracted dictionary will be saved.
        """
        btssm_version = btssm_version.strip() if btssm_version is not None else None
        param_dictionary_path = param_dictionary_path.strip() if param_dictionary_path is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            session.btssm.get_parameter_dictionary(btssm_version, param_dictionary_path)
